values
('bmlt-immuno-mcq-001','BMLT','BMLT NHPC Licensing','mcq','free',200,'{"question":"Which cell is primarily responsible for producing antibodies?","translation":"Antibody उत्पादन गर्ने मुख्य कोशिका कुन हो?","options":["T lymphocyte","B lymphocyte","Neutrophil","Monocyte"],"correctIndex":1,"explanation":"Plasma cells derived from B lymphocytes secrete antibodies.","explanationNe":"B lymphocyte बाट बनेका plasma cells ले antibody उत्पादन गर्छन्।","topic":"Immunology & Serology"}'::jsonb,true),
